function dayTime(){const total=900+time/2+clockOffset,minute=((total%1440)+1440)%1440;return{total,day:Math.floor(total/1440),minute,hour:Math.floor(minute/60),night:minute>=1140||minute<330,dusk:minute>=1020&&minute<1140,rush:(minute>=420&&minute<540)||(minute>=1020&&minute<1140)};}
function eveningBell(){eveningCount++;eveningUntil=time+34;say('夕方のチャイムです。気をつけて、おうちに帰りましょう。','ゆうがたのチャイムです。きをつけて、おうちにかえりましょう。','17:00 · 夕焼け小焼け。慢慢回家，看看爸爸做好饭了没有。');toast('17:00 ♪ 夕焼け小焼け');let at=time+3;eveningQueue=EVENING_MELODY.map(([note,beats])=>{const e={at,note,duration:beats*.5};at+=beats*.5;return e;});eveningUntil=at;}
function advanceTo(minute){const c=dayTime(),delta=(minute-c.minute+1440)%1440;clockOffset+=delta;closeModal();toast('休憩して、またおでかけ。');updateUI();}
function familyWalk(points,f){const lens=points.slice(1).map((p,i)=>Math.hypot(p[0]-points[i][0],p[1]-points[i][1]));let d=f*lens.reduce((a,b)=>a+b,0);for(let i=0;i<lens.length;i++){if(d<=lens[i]||i===lens.length-1){const u=clamp(d/lens[i],0,1);return{x:points[i][0]+(points[i+1][0]-points[i][0])*u,y:points[i][1]+(points[i+1][1]-points[i][1])*u};}d-=lens[i];}}
function motherState(){const t=time%112;if(t<42)return{state:'sofa',x:330,y:292};if(t<55){const f=(t-42)/13;return{state:'walking',...familyWalk([[330,335],[420,470],[660,470],[800,470],[800,525]],f)};}if(t<97)return{state:'futon',x:800,y:553};const f=(t-97)/15;return{state:'walking',...familyWalk([[800,525],[800,470],[660,470],[420,470],[330,335]],f)};}
function fatherState(){const t=time%150;if(t<28)return{state:'cooking',x:950,y:355};if(t<40){const f=(t-28)/12;return{state:'serving',...familyWalk([[950,355],[950,430],[670,460]],f)};}if(t<50){const f=(t-40)/10;return{state:'walking',...familyWalk([[670,460],[665,650],[980,650],[980,570]],f)};}if(t<94)return{state:'working',x:980,y:570};if(t<138){const f=(t-94)/44;return{state:'cleaning',x:900-630*f,y:655+Math.sin(f*Math.PI*4)*9};}const f=(t-138)/12;return{state:'walking',...familyWalk([[270,650],[980,650],[980,355],[950,355]],f)};}
