function updateLife(){const c=dayTime(),sig=c.hour+":"+c.rush;if(sig!==lifeUISignature){lifeUISignature=sig;updateUI();}if(c.minute>=1020&&eveningDay!==c.day){eveningDay=c.day;if(c.minute<1021)eveningBell();}for(const e of eveningQueue.filter(e=>!e.played&&e.at<=time)){e.played=true;if(!e.note)continue;eveningNotes++;tone(440*Math.pow(2,(e.note-69)/12),Math.max(.1,e.duration*.9),'sine',.08);tone(440*Math.pow(2,(e.note-57)/12),Math.max(.1,e.duration*.65),'sine',.012);}const cycle=Math.floor(time/150);if(time%150>=40&&homeLife.servedCycle!==cycle){homeLife.servedCycle=cycle;homeLife.ready=true;if(scene==='home'){chime();toast('大伟博：ごはんができたよ！餐桌旁按 E 吃饭。');}}for(const t of homeToys){if(!t.motion)continue;const m=t.motion,f=clamp((time-m.start)/m.duration,0,1);t.x=m.from.x+(m.to.x-m.from.x)*ease(f);t.y=m.from.y+(m.to.y-m.from.y)*f;if(f===1)t.motion=null;}}
