function monoArrival(start,dir,st){return start+(dir===1?st:monoNames.length-1-st)*40;}
function monoState(start,dir){const age=time-start,last=monoNames.length-1,origin=dir===1?0:last;if(age<0)return{pos:origin-dir*Math.min(2,-age/12),door:false};for(let i=0;i<=last;i++){const at=origin+i*dir,t=age-i*40;if(t>=0&&t<14)return{pos:at,at,door:t>1.7&&t<12,remaining:14-t};if(i<last&&t>=14&&t<40)return{pos:at+dir*ease((t-14)/26),door:false,next:at+dir};}const dest=dir===1?last:0;if(monoRide?.start===start&&monoRide?.dir===dir)return{pos:dest,at:dest,door:true,remaining:0};return{pos:dest+dir*(age-last*40-14)/12,door:false};}
function monoServices(){const k=Math.floor(time/74),out=[];for(let n=k-Math.ceil((monoNames.length*40+37)/74)-1;n<=k+1;n++)for(const dir of[1,-1]){const start=n*74+(dir===1?0:37);out.push({start,dir,...monoState(start,dir)});}return out;}
function monoBoardable(){return monoServices().find(t=>t.dir===monoDirection&&t.at===monoStation&&t.door);}
