function mainPlatformTrains(){const k=Math.floor(time/MAIN_HEADWAY),out=[];for(let n=k-55;n<=k+4;n++){const tr=makeMainTrain(n,mainDirection),call=tr.calls.find(c=>c.station===mainStation);if(call)out.push({tr,s:trainState(tr),call});}return out;}
function mainBoardable(){return mainPlatformTrains().find(o=>o.call.stop&&!(o.tr.service.id==='liner'&&o.tr.dir===-1&&mainStation===3)&&o.call!==o.tr.calls.at(-1)&&o.s.station===mainStation&&o.s.door);}
function mainDepartures(){return mainPlatformTrains().filter(o=>o.call.dep>time).sort((a,b)=>a.call.arr-b.call.arr).slice(0,3);}
function mainPois(){if(scene==='keioPassage')return[{id:'passageBack',x:170,y:570,label:'元のホームへ戻る'},{id:'passageExit',x:1030,y:570,label:'案内の先へ歩く · 乗り換え'}];if(scene==='keioHall')return[{id:'mainGate',x:600,y:mainPaid?320:455,label:mainPaid?'ICタッチ · 出場':'ICタッチ · 入場'},{id:'mainCharge',x:1040,y:mainPaid?330:480,label:'チャージ +300'},{id:'mainWest',x:300,y:205,label:westName()+'方面ホーム'},{id:'mainEast',x:900,y:205,label:'新宿方面ホーム'},{id:'mainOutside',x:600,y:715,label:'駅前へ出る'},...(mainPaid&&mainStation===TAKAHATA?[{id:'mainLink',x:600,y:190,label:'動物園線 1番線へ歩く'}]:[])];if(scene==='keioPlatform')return[...(LINER_STOPS.includes(mainStation)?[{id:'mainLiner',x:865,y:620,label:'ライナーチケット 発売機'}]:[]),{id:'mainDown',x:170,y:630,label:'階段 · 改札と乗換'},{id:'mainTrain',x:600,y:450,label:'京王線に乗る'},{id:'mainStamp',x:1030,y:615,label:'駅スタンプ'}];if(scene==='keioTown')return[...(mainStation<MAIN_CHOFU?[{id:'mainView',x:225,y:475,label:MAIN_STATIONS[mainStation].place+' · 見る'}]:[]),{id:'mainEntrance',x:600,y:350,label:'京王線の駅に入る'},{id:'mainLocal',x:930,y:550,label:MAIN_THEMES[mainStation]+' · 話す'},{id:'mainFind',x:300,y:590,label:'まちの記念カードを見つける'}];return null;}
function beginKeioTransfer(source,target){keioTransfer={source,target};if(!keioOrigin)keioOrigin=source==='saga'?D.stations[entry??station].id:source==='zoo'?(zooEntry===1?'zoo':'takahata'):MAIN_STATIONS[mainEntry??mainStation].id;go('keioPassage',170,570);toast('改札内の乗り換えです。案内に沿って歩こう。');}
function finishKeioTransfer(back=false){const t=keioTransfer,dest=back?t.source:t.target;if(!back){if(t.source==='saga'){paid=false;entry=null;}if(t.source==='main'){mainPaid=false;mainEntry=null;}if(t.source==='zoo'){zooPaid=false;zooEntry=null;}}if(dest==='saga'){station=0;direction=1;paid=true;entry=0;go('concourse',600,280);}else if(dest==='zoo'){zooStation=0;zooPaid=true;zooEntry=0;go('zooHall',600,280);}else{if(!back)mainStation=t.source==='saga'?MAIN_CHOFU:TAKAHATA;mainDirection=-1;mainPaid=true;mainEntry=mainStation;go('keioHall',600,280);}keioTransfer=null;}
