 if(id==='passageBack'||id==='passageExit'){finishKeioTransfer(id==='passageBack');return true;}
 if(id==='mainGate'){if(mainPaid){const fare=(keioOrigin??MAIN_STATIONS[mainEntry].id)===MAIN_STATIONS[mainStation].id?0:80;if(profile.ic<fare){toast('余额不足，请到同侧充值机精算。');return true;}profile.ic-=fare;if(mainStation===45&&step===6)setStep(7);mainPaid=false;mainEntry=null;keioOrigin=null;toast('ピッ · 出場 −'+fare+' 游戏円');}else{if(profile.ic<80){toast('请先在右边充值。');return true;}mainPaid=true;mainEntry=mainStation;keioOrigin=MAIN_STATIONS[mainStation].id;unlock('mainVisited',mainStation);toast('ピッ · 京王線へようこそ');}save();tone(1320,.14);gateUntil=time+1.1;transition={start:time,from:{...player},to:{x:600,y:mainPaid?312:465},duration:1};path=[];updateUI();return true;}
 if(id==='mainCharge'){if(profile.coins<300){openModal('<h2>駅員の旅行援助</h2><button data-do="aid">领取援助后再充值</button>');return true;}profile.coins-=300;profile.ic+=300;save();chime();updateUI();toast('チャージ +300');return true;}
 if(id==='mainWest'||id==='mainEast'){if(!mainPaid){toast('先刷 IC 卡进站。');return true;}mainDirection=id==='mainWest'?1:-1;go('keioPlatform',170,620);if(mainStation===45&&step===2)setStep(3);return true;}
