function makeMainTrain(k,dir){
 for(let n=mainBuilt[dir]+1;n<=k;n++){
  const route=RAIL_ROUTES[((n%3)+3)%3],round=Math.floor(n/3),kind=route.id==='hashimoto'?['local','express','rapid','section','local','liner'][((round%6)+6)%6]:['local','express','local','express','local','liner'][((round%6)+6)%6];
  const service={...D.services.find(s=>s.id===kind)},order=dir===1?[...route.path]:[...route.path].reverse();
  let stops=kind==='local'?order:kind==='express'?[0,1,3,9,15,21,22,24,26,30,31,32,33,34,35,36,37,39,43,44,46,48]:kind==='rapid'?[0,1,3,4,5,7,...Array.from({length:40},(_,i)=>9+i)]:kind==='section'?[0,1,3,5,9,10,11,...Array.from({length:34},(_,i)=>15+i)]:LINER_STOPS;
  service.stops=order.filter(i=>stops.includes(i));
  const prev=mainCache.get(`${n-1}:${dir}`);let t=n*MAIN_HEADWAY+(dir===-1?23:0),calls=[];
  for(let i=0;i<order.length;i++){const st=order[i],stop=service.stops.includes(st),prior=prev?.calls.find(c=>c.station===st),arr=Math.max(t,prior?prior.dep+18:t),dep=arr+(stop?14:0);calls.push({station:st,arr,dep,stop,ordinal:i});let travel=15.6;if(st>=38&&order[i+1]>=38)travel=D.distances[Math.min(st,order[i+1])-37]*7.8;t=dep+travel;}
  const indices=calls.map((c,i)=>c.stop?i:-1).filter(i=>i>=0);
  for(let j=0;j<indices.length-1;j++){const a=indices[j],b=indices[j+1];for(let h=a+1;h<b;h++){const ratio=(h-a)/(b-a);let lo=0,hi=1;for(let z=0;z<24;z++){const m=(lo+hi)/2;if(ease(m)<ratio)lo=m;else hi=m;}calls[h].arr=calls[a].dep+(calls[b].arr-calls[a].dep)*(lo+hi)/2;calls[h].dep=calls[h].arr;}}
  mainCache.set(`${n}:${dir}`,{rail:true,id:`through:${n}:${dir}`,k:n,dir,route:route.id,destination:dir===1?route.name:'新宿',path:order,service,calls,end:calls.at(-1).dep+10});mainBuilt[dir]=n;
 }
 return mainCache.get(`${k}:${dir}`);
}
function throughState(tr,t){const stops=tr.calls.filter(c=>c.stop),first=stops[0],final=stops.at(-1);if(t<first.arr)return{pos:-Math.max(0,(first.arr-t)/18),next:first.station,state:'approach',door:false};if(tr===mainRide&&t>=final.dep)return{pos:final.ordinal,station:final.station,next:final.station,state:'terminal',door:true};for(const c of stops)if(t>=c.arr&&t<c.dep)return{pos:c.ordinal,station:c.station,next:c.station,state:t<c.arr+1.7?'braking':t>c.dep-2?'closing':'stopped',door:t>=c.arr+1.7&&t<=c.dep-2,remaining:c.dep-t};const a=[...stops].reverse().find(c=>c.dep<=t),b=stops.find(c=>c.arr>t);if(b)return{pos:a.ordinal+(b.ordinal-a.ordinal)*ease(clamp((t-a.dep)/(b.arr-a.dep),0,1)),next:b.station,state:'running',door:false};return{pos:final.ordinal+(t-final.dep)/16,next:null,state:'leaving',door:false};}
