const SEAT_X=[100,165,230,295,360,835,900,965,1030,1095];let sitting=null;const seatAssignments=new Map();
function carScene(){return ['train','monoCar','zooCar','keioCar'].includes(scene);}
function rawCarActors(){let list=[];let trip='';if(scene==='train'||scene==='keioCar'){const tr=scene==='train'?onTrain:mainRide;list=passengers(tr);trip=tr.id;}else if(scene==='monoCar'){trip='mono:'+monoRide.start+':'+monoRide.dir;list=passengers({id:trip,calls:monoNames.map((_,i)=>({station:monoRide.dir===1?i:monoNames.length-1-i,arr:monoRide.start+i*40,dep:monoRide.start+i*40+14,stop:true}))});}else if(scene==='zooCar'){const st=zooState(),leaving=st.at!==undefined&&st.age>=2&&st.age<8,boarding=st.at!==undefined&&st.age>=8&&st.age<14;const period=Math.floor(time/56),age=((time%56)+56)%56;trip='zoo:'+period;const cohort=age<8?period-1:period;list=[0,1].map(i=>({id:'zoo:'+cohort+':'+i,phase:leaving?'alighting':boarding?'boarding':'seated',progress:leaving?(st.age-2)/6:boarding?(st.age-8)/6:1,color:i?'#849dac':'#b89b7f'}));}if(dayTime().rush&&carScene()&&!((onTrain||mainRide)?.service.id==='liner'))for(let i=0;i<16;i++)list.push({id:trip+':rush:'+i,phase:'seated',progress:1,color:['#8f9fad','#a5ac86','#b59a87','#a28da5'][i%4]});return list;}
function carActors(){const raw=rawCarActors(),used=new Set(sitting?[sitting.index]:[]),live=new Set(raw.map(p=>p.id));for(const id of seatAssignments.keys())if(!live.has(id))seatAssignments.delete(id);const assigned=new Map();for(const p of raw){const old=seatAssignments.get(p.id),blocking=p.phase!=='alighting'||p.progress<.5;if(old>=0&&blocking&&!used.has(old)){assigned.set(p.id,old);used.add(old);}}
return raw.map(p=>{const blocking=p.phase!=='alighting'||p.progress<.5;let i=assigned.get(p.id);if(i===undefined&&!blocking)i=seatAssignments.get(p.id)??-1;if(i===undefined){const empty=SEAT_X.map((_,i)=>i).filter(i=>!used.has(i));i=blocking&&empty.length?empty[Math.floor(Math.random()*empty.length)]:-1;if(i>=0)used.add(i);seatAssignments.set(p.id,i);}return {...p,seatIndex:i,blocking};});}
function seatSlots(){const actors=carActors();return SEAT_X.map((x,i)=>({index:i,x,occupied:actors.some(p=>p.blocking&&p.seatIndex===i),selected:sitting?.index===i}));}
function seatPois(){return seatSlots().map(s=>({id:'carSeat'+s.index,x:s.x,y:605,label:'座席 '+(s.index+1)+(s.occupied?' · 使用中':' · Eで座る')}));}
