 $('speedControls').hidden=!carScene();document.querySelectorAll('[data-speed]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.speed)===rideSpeed));$('balance').textContent=profile.ic;$('coins').textContent='◉ '+profile.coins;$('count').textContent=Object.values(profile.toys).reduce((a,b)=>a+b,0);document.body.classList.toggle('child',profile.child);
