 if(step===4&&scene!=='keioCar'&&scene!=='train'&&station!==MINAMI){$('missionTitle').textContent='南大沢へ、戻ろう';hint=`现在是${D.stations[station].name}。乘${station<MINAMI?'橋本':'調布'}方向的各停、快速或区間急行，回南大沢继续扭蛋任务。`;}if(scene==='train')hint='车厢内可自由移动。下车前走到中间车门，开门时按 E；来不及就会坐过站。';if(profile.activeErrand)hint=errandHint();if(scene==='restaurant')hint='走到四人桌旁按 E 坐下。机器人送肉后，E 下锅；煮熟再按 E 开动，最后 E 起身。';if(scene.startsWith('mono'))hint=scene==='monoWalk'?'沿步行者通道走到「改札へ」，进入单轨车站。':scene==='monoHall'?(monoPaid?'进站后走到左边楼梯，上月台等车；出站请刷 IC 卡。':'刷 IC 卡进入单轨系统，再走上楼梯。京王与单轨分别扣费。'):scene==='monoCar'?'窗外是高架风景。停车开门时走到中间车门按 E 下车。':'在黄线内等车，开门后 E 上车。高幡不動是本版体验边界，可搭返程回来。';
 if(scene==='monoTown'&&monoStation>=5)hint=monoQuestHint();if(scene==='monoTown'&&monoStation===4)hint='两座车站分别属于京王和单轨。换乘时先刷卡出站，再走到另一座车站。回家可乘单轨往多摩センター。';
 if(scene.startsWith('zoo'))hint=scene==='zooHall'?(zooPaid?'进站后走到左侧楼梯去候车。出站先刷卡，再步行换乘单轨。':'先刷卡进入京王改札。京王与单轨分别扣费，余额不足可在右侧充值。'):scene==='zooCar'?'中途没有程久保站。终点开门时到中间车门按 E；不下车就会跟车折返。':'等列车驶入、开门后按 E 上车。高幡不動和多摩動物公園之间直达。';
 if(scene.startsWith('keio'))hint=scene==='keioCar'?'空位前按 E 坐下，再按 E 起身。开门时去中间车门下车，错过会继续前进。':scene==='keioPassage'?'向右步行到通道尽头，按 E 到另一条线；这里不用重新刷卡。':'先刷 IC 卡，再走到方向楼梯。看清发车牌目的地：橋本／京王八王子／高尾山口，列车直通新宿。調布不用换车。';if(scene==='akibaPark'){$('missionTitle').textContent='ピラミッドのすべり台';}if(scene==='akibaPark')hint=parkTop?'金字塔顶端到了！在长滑梯入口按 E，从山坡滑下去。':'走到金字塔左侧阶梯，按 E 一步步爬到顶端，再滑长滑梯。';if(scene==='home')hint='餐桌右边按 E，摆上购物袋里的食品或吃东西。爸爸做的饭在餐桌前吃。玩具旁按 E 让它动起来；布团旁可休息到早晨、黄昏或夜间。';if(carScene()&&dayTime().rush)hint='通勤高峰，人很多！没有空位时可以站着乘车；开门后到中央车门按 E 下车。';$('hint').textContent=profile.child?hint:'近くの場所で E · 路線図で行き先を確認';$('progress').innerHTML=Array.from({length:8},(_,i)=>`<i class="${i<step?'done':i===step?'current':''}"></i>`).join('');
