function errandHint(){const id=profile.activeErrand;if(id==='tama'&&station!==TAMA)return `先到京王多摩センター：${station>TAMA?'調布':'橋本'}方向，${platformNumber(station>TAMA?-1:1)} 番線。到站按 E 下车，刷卡出站。`;if(id==='tama')return `多摩センター探险：公园、图书馆、パルテノン、单轨见学 ${['park','library','parthenon','mono'].filter(k=>profile.tamaFinds.includes(k)).length}/4。去路線図选择步行地点。`;const st=D.stations.find(s=>s.id===id);return st?(profile.souvenirs.includes(id)?`带着${st.item}去${st.landmark}交任务。`:`${st.name}：${st.task}。在地图中选择「${st.item}を見つける」。`):'';}
