 dialog(which==='landmark'?st.landmark:st.place,`${st.word}を、見つけたね。`,`${st.reading}を、みつけたね。`,special[st.id]||st.tag,`<div class="row"><button data-do="localQuest">看看本地任务</button></div>`);
